//! Build-time codegen for `trees.json`: dump order kept, null rows skipped
//! like the old reader.

/// Render `trees_generated.rs` from the parsed dump.
pub fn generate(manifest_dir: &str) {
    let parsed = crate::parse_dump(manifest_dir, "trees");
    let rows = crate::dump_rows(&parsed, "trees");
    let mut generated = String::from(
        "// Generated by rs/crates/gamedata/build.rs from gamedata/data/trees.json - do not edit.\n\
         pub static ALL: &[super::StaticTreeTier] = &[\n",
    );
    for row in rows {
        if row.is_null() {
            continue;
        }
        generated.push_str(&format!(
            "    super::StaticTreeTier {{ trees: {}, level: {}, product: \"{}\", exp: {}, \
             product_members: {} }},\n",
            crate::render_str_array(row, "trees"),
            row.get("level").as_i64().unwrap_or(0),
            crate::escape_for_rust_literal(row.get("product").as_str().unwrap_or("")),
            row.get("exp").as_i64().unwrap_or(0),
            crate::render_opt_flag(row, "product_members"),
        ));
    }
    generated.push_str("];\n");
    crate::emit_generated("trees_generated.rs", &generated);
}
